import{_ as e,o as i,c as n,ak as o}from"./chunks/framework.sbZkgmEx.js";const a="/projects/AiBlock/en/advanced-kit/assets/0.B8qt0VtG.webp",r="/projects/AiBlock/en/advanced-kit/assets/3.BRiqQ6vV.webp",h=JSON.parse('{"title":"1. Kit Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"docs/1. Kit Introduction.md","filePath":"docs/1. Kit Introduction.md"}'),s={name:"docs/1. Kit Introduction.md"};function l(d,t,c,g,m,p){return i(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="_1-kit-introduction" tabindex="-1">1. Kit Introduction <a class="header-anchor" href="#_1-kit-introduction" aria-label="Permalink to &quot;1. Kit Introduction&quot;">​</a></h1><h2 id="_1-1-kit-overview" tabindex="-1">1.1 Kit Overview <a class="header-anchor" href="#_1-1-kit-overview" aria-label="Permalink to &quot;1.1 Kit Overview&quot;">​</a></h2><p>This kit is specifically designed for elementary students aged 7 to 12. The AiBlock TechPower Advanced Kit features an integrated intelligent controller at its core, accompanied by multiple sensor modules, motorized block motors, block servos, and a comprehensive set of mechanical building blocks. It supports dual learning modes consisting of purely mechanical assembly and intelligent programming.</p><p>The kit comes with 48 creative build projects and the WonderLab graphical programming platform. It constructs a systematic learning path step by step, transitioning from mechanical transmission principles to intelligent sensor interactions, and from fundamental programming logic to multi-module coordinated control. The extensive block components allow assembling diverse models, such as hand-cranked fans, bionic robots, mecha warriors, smart vehicles, and amusement rides. These projects cover interdisciplinary fields including mechanical engineering, bionic design, intelligent sensing, and automated control. Through hands-on practice, this kit cultivates spatial thinking, logical reasoning, and engineering innovation abilities, providing a systematic enlightenment in scientific innovation.</p><img loading="lazy" height="2635" width="3828" src="'+a+'" class="common_img" style="width:800px;"><h2 id="_1-2-product-features" tabindex="-1">1.2 Product Features <a class="header-anchor" href="#_1-2-product-features" aria-label="Permalink to &quot;1.2 Product Features&quot;">​</a></h2><ol><li><p><strong>Tiered Dual Learning Modes</strong>: The kit supports two distinct learning pathways, including non-controller mechanical assembly and controller-based intelligent programming. Beginners can start with hands-on building and progressively advance to coding, which significantly lowers the barrier to entry for STEAM education while catering to both classroom instruction and home practice.</p></li><li><p><strong>Multi-Functional Integrated Controller</strong>: Equipped with an integrated smart controller featuring 4 block servo and block motor ports, 4 long motor ports, 4 sensor ports, 2 programmable buttons, and an onboard buzzer. Each port zone is clearly labeled, and power output remains stable, enabling precise and straightforward hardware control.</p></li><li><p><strong>Comprehensive Mechanical Block Accessories</strong>: Packed with an ample supply of transmission and structural building blocks, covering more than ten types of mechanical components such as gear drives, worm gears, crank linkages, rack and pinion mechanisms, fixed pulleys, and track transmissions. Diverse parts support open-ended creative builds while exercising hands-on practical skills and logical thinking.</p></li><li><p><strong>Dedicated Graphical Programming Software</strong>: The WonderLab drag-and-drop visual programming platform operates simply without complex code, supporting real-time debugging in online mode alongside program uploading. It seamlessly matches course project programs, reducing the entry threshold for coding and fostering computational thinking and logical control skills.</p></li><li><p><strong>Multi-Sensor Fusion and Interaction</strong>: Equipped with multiple sensor types, including sound, light, touch, knob, infrared obstacle avoidance, ultrasonic, and 6-channel line follower sensors. It supports diverse interactive methods such as sound control, light sensing, touch response, distance measurement, and line tracking, progressing from single-sensor control to multi-sensor coordinated decision-making to establish a comprehensive cognitive framework for intelligent systems.</p></li><li><p><strong>Multi-Actuator Coordinated Control</strong>: Incorporates multiple output modules, including block motors, servos, RGB lights, dot matrix displays, and buzzers. It supports multi-dimensional feedback such as speed control, angular positioning, color rendering, graphic animations, and sound effects. This synergy achieves simultaneous coordination between mechanical motion and audiovisual effects, enriching model expressiveness and interactive engagement.</p></li></ol><h2 id="_1-3-product-specifications" tabindex="-1">1.3 Product Specifications <a class="header-anchor" href="#_1-3-product-specifications" aria-label="Permalink to &quot;1.3 Product Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Item</th><th style="text-align:left;">Specification</th></tr></thead><tbody><tr><td style="text-align:left;">Brand</td><td style="text-align:left;">Hiwonder</td></tr><tr><td style="text-align:left;">Model</td><td style="text-align:left;">AiBlock TechPower Advanced Kit</td></tr><tr><td style="text-align:left;">Programming software</td><td style="text-align:left;">WonderLab Graphical Programming / Hiwonder Python Editor</td></tr><tr><td style="text-align:left;">Recommended age</td><td style="text-align:left;">6+</td></tr><tr><td style="text-align:left;">Electronic modules</td><td style="text-align:left;">Ultrasonic sensor, light sensor, sound sensor, knob module, infrared obstacle avoidance sensor, touch sensor, 6-channel line follower sensor, 180° block servo, 360° block motor, dot matrix module, RGB light module</td></tr><tr><td style="text-align:left;">Communication port</td><td style="text-align:left;">USB port</td></tr><tr><td style="text-align:left;">Block count</td><td style="text-align:left;">750+</td></tr><tr><td style="text-align:left;">Material</td><td style="text-align:left;">ABS</td></tr><tr><td style="text-align:left;">Weight including packaging</td><td style="text-align:left;">2.3 kg</td></tr><tr><td style="text-align:left;">Package dimensions</td><td style="text-align:left;">365 × 270 × 120 mm</td></tr></tbody></table><h2 id="_1-4-packing-list" tabindex="-1">1.4 Packing List <a class="header-anchor" href="#_1-4-packing-list" aria-label="Permalink to &quot;1.4 Packing List&quot;">​</a></h2><img loading="lazy" height="3266" width="4399" src="'+r+'" class="common_img" style="width:800px;">',11)])])}const f=e(s,[["render",l]]);export{h as __pageData,f as default};
